#!/usr/bin/env python3
"""Global Airbnb Cross-Market Analysis Report Generator."""

import pandas as pd
import numpy as np
import plotly.graph_objects as go
import plotly.express as px
from plotly.subplots import make_subplots
import json
import os

# ── Load & Clean ──────────────────────────────────────────────────────────

df = pd.read_csv('/app/benchmark/data.csv')

# Parse dates
df['last_review'] = pd.to_datetime(df['last_review'], errors='coerce')
df['scrape_date'] = pd.to_datetime(df['scrape_date'], errors='coerce')

# Price: convert to numeric, coerce errors
df['price'] = pd.to_numeric(df['price'], errors='coerce')

# Flag professional hosts
df['is_professional'] = df['calculated_host_listings_count'] >= 5

CITIES = sorted(df['city'].dropna().unique())
CITY_ORDER = df.groupby('city')['price'].median().sort_values(ascending=False).index.tolist()

# ── Helper Functions ──────────────────────────────────────────────────────

def fig_to_html(fig, div_id=None):
    """Convert plotly figure to HTML div with responsive sizing."""
    fig.update_layout(
        template='plotly_white',
        font_family='Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        margin=dict(l=10, r=10, t=40, b=10),
    )
    if div_id:
        html = fig.to_html(full_html=False, include_plotlyjs=False, div_id=div_id)
    else:
        html = fig.to_html(full_html=False, include_plotlyjs=False)
    return html

# ── KPI Calculations ──────────────────────────────────────────────────────

kpi_data = {}
for city in CITY_ORDER:
    city_df = df[df['city'] == city]
    prices = city_df['price'].dropna()
    total = len(city_df)

    kpi_data[city] = {
        'total_listings': total,
        'median_price': prices.median(),
        'mean_price': prices.mean(),
        'price_count': len(prices),
        'price_missing': total - len(prices),
        'entire_home_pct': (city_df['room_type'] == 'Entire home/apt').mean() * 100,
        'private_room_pct': (city_df['room_type'] == 'Private room').mean() * 100,
        'shared_room_pct': (city_df['room_type'] == 'Shared room').mean() * 100,
        'hotel_room_pct': (city_df['room_type'] == 'Hotel room').mean() * 100,
        'professional_host_pct': city_df['is_professional'].mean() * 100,
        'avg_reviews_per_month': city_df['reviews_per_month'].dropna().mean(),
        'median_reviews_per_month': city_df['reviews_per_month'].dropna().median(),
        'total_reviews': city_df['number_of_reviews'].sum(),
        'mean_availability': city_df['availability_365'].mean(),
        'median_availability': city_df['availability_365'].median(),
        'avg_min_nights': city_df['minimum_nights'].mean(),
        'median_min_nights': city_df['minimum_nights'].median(),
        'listings_with_reviews': (city_df['number_of_reviews'] > 0).sum(),
        'listings_with_reviews_pct': (city_df['number_of_reviews'] > 0).mean() * 100,
        'avg_reviews_ltm': city_df['number_of_reviews_ltm'].mean(),
        'recent_review_pct': (city_df['last_review'] >= pd.Timestamp('2025-01-01')).mean() * 100
        if city_df['last_review'].notna().any() else 0,
    }

# ── Professional host concentration ───────────────────────────────────────

host_conc = df.groupby('city').apply(
    lambda g: pd.Series({
        'top1_share': g.nlargest(1, 'calculated_host_listings_count')['calculated_host_listings_count'].values[0],
        'top5_total': g.nlargest(5, 'calculated_host_listings_count')['calculated_host_listings_count'].sum(),
        'unique_hosts': g['host_id'].nunique(),
        'listings_per_host': len(g) / g['host_id'].nunique(),
        'multi_listing_pct': (g.groupby('host_id').size() >= 5).mean() * 100 if g['host_id'].nunique() > 0 else 0,
    })
).reset_index()

# ── Price by room type ────────────────────────────────────────────────────

price_by_rt = df.dropna(subset=['price']).groupby(['city', 'room_type'])['price'].agg(
    ['median', 'mean', 'count', 'std']
).reset_index()

# ── Reviews per month by city and room type ───────────────────────────────

reviews_by_rt = df.dropna(subset=['reviews_per_month']).groupby(['city', 'room_type'])['reviews_per_month'].mean().reset_index()

# ══════════════════════════════════════════════════════════════════════════
#  CHARTS
# ══════════════════════════════════════════════════════════════════════════

chart_id = 0
charts = {}

# ── Chart 1: Median Price by City (Bar) ───────────────────────────────────

chart_id += 1
fig1 = go.Figure()
prices_med = [kpi_data[c]['median_price'] for c in CITY_ORDER]
fig1.add_trace(go.Bar(
    x=CITY_ORDER,
    y=prices_med,
    marker_color=['#0D47A1' if c == CITY_ORDER[0] else '#1E88E5' if c == CITY_ORDER[-1] else '#42A5F5' for c in CITY_ORDER],
    text=[f'${v:,.0f}' for v in prices_med],
    textposition='outside',
    hovertemplate='%{x}: $%{y:,.0f}<extra></extra>',
))
fig1.update_layout(
    title={'text': 'Median Nightly Price by City (USD)', 'font': {'size': 16, 'color': '#1a1a2e'}},
    xaxis_title=None,
    yaxis_title='Median Price (USD)',
    showlegend=False,
    height=420,
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['median_price_bar'] = fig_to_html(fig1, 'chart_median_price')

# ── Chart 2: Price Distribution Box Plot ──────────────────────────────────

chart_id += 1
fig2 = go.Figure()
for city in CITY_ORDER:
    prices = df[(df['city'] == city)]['price'].dropna()
    q1, q3 = prices.quantile(0.25), prices.quantile(0.75)
    iqr = q3 - q1
    upper = q3 + 1.5 * iqr
    prices_clipped = prices[prices <= upper]
    fig2.add_trace(go.Box(
        y=prices_clipped,
        name=city,
        boxpoints=False,
        marker_color='#42A5F5',
        line_color='#1a1a2e',
    ))
fig2.update_layout(
    title={'text': 'Price Distribution by City (Outliers Removed)', 'font': {'size': 16, 'color': '#1a1a2e'}},
    yaxis_title='Nightly Price (USD)',
    showlegend=False,
    height=450,
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['price_box'] = fig_to_html(fig2, 'chart_price_box')

# ── Chart 3: Price by Room Type (Grouped Bar) ─────────────────────────────

chart_id += 1
room_types_present = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
colors_rt = {'Entire home/apt': '#1E88E5', 'Private room': '#43A047',
             'Shared room': '#FB8C00', 'Hotel room': '#8E24AA'}

fig3 = go.Figure()
for rt in room_types_present:
    rt_data = price_by_rt[price_by_rt['room_type'] == rt]
    city_meds = []
    for c in CITY_ORDER:
        match = rt_data[rt_data['city'] == c]
        city_meds.append(match['median'].values[0] if len(match) > 0 else None)
    fig3.add_trace(go.Bar(
        name=rt,
        x=CITY_ORDER,
        y=city_meds,
        marker_color=colors_rt.get(rt, '#999'),
        text=[f'${v:,.0f}' if pd.notna(v) else 'N/A' for v in city_meds],
        textposition='outside',
        textfont_size=9,
    ))

fig3.update_layout(
    title={'text': 'Median Price by City & Room Type', 'font': {'size': 16, 'color': '#1a1a2e'}},
    barmode='group',
    xaxis_title=None,
    yaxis_title='Median Price (USD)',
    height=450,
    legend=dict(orientation='h', yanchor='bottom', y=1.02, xanchor='right', x=1),
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['price_by_roomtype'] = fig_to_html(fig3, 'chart_price_roomtype')

# ── Chart 4: Room Type Composition (100% Stacked Bar) ─────────────────────

chart_id += 1
room_types_order = ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']
fig4 = go.Figure()
for i, rt in enumerate(room_types_order):
    pcts = []
    for c in CITY_ORDER:
        pcts.append(kpi_data[c][f'{rt.lower().replace(" ", "_").replace("/", "_")}_pct'])
    fig4.add_trace(go.Bar(
        name=rt,
        x=CITY_ORDER,
        y=pcts,
        marker_color=colors_rt.get(rt, '#999'),
        text=[f'{v:.1f}%' for v in pcts],
        textposition='inside',
        textfont_color='white',
        textfont_size=10,
    ))

fig4.update_layout(
    title={'text': 'Room Type Composition by City', 'font': {'size': 16, 'color': '#1a1a2e'}},
    barmode='stack',
    xaxis_title=None,
    yaxis_title='Share of Listings (%)',
    height=420,
    legend=dict(orientation='h', yanchor='bottom', y=1.02, xanchor='right', x=1),
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False, ticksuffix='%'),
)
charts['room_type_comp'] = fig_to_html(fig4, 'chart_roomtype_comp')

# ── Chart 5: Professional Host Share ──────────────────────────────────────

chart_id += 1
pro_pcts = [kpi_data[c]['professional_host_pct'] for c in CITY_ORDER]
fig5 = go.Figure()
fig5.add_trace(go.Bar(
    x=CITY_ORDER,
    y=pro_pcts,
    marker=dict(
        color=pro_pcts,
        colorscale='Blues',
        showscale=False,
        line=dict(color='#1a1a2e', width=0.5),
    ),
    text=[f'{v:.1f}%' for v in pro_pcts],
    textposition='outside',
))
fig5.update_layout(
    title={'text': 'Professional Host Share by City (Hosts with 5+ Listings)', 'font': {'size': 16, 'color': '#1a1a2e'}},
    xaxis_title=None,
    yaxis_title='Share of Listings (%)',
    showlegend=False,
    height=400,
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False, ticksuffix='%'),
)
charts['professional_host'] = fig_to_html(fig5, 'chart_pro_host')

# ── Chart 6: Reviews per Month ────────────────────────────────────────────

chart_id += 1
fig6 = go.Figure()
avg_rpm = [kpi_data[c]['avg_reviews_per_month'] for c in CITY_ORDER]
fig6.add_trace(go.Bar(
    x=CITY_ORDER,
    y=avg_rpm,
    marker_color='#43A047',
    text=[f'{v:.2f}' for v in avg_rpm],
    textposition='outside',
))
fig6.update_layout(
    title={'text': 'Average Reviews per Month by City (Demand Proxy)', 'font': {'size': 16, 'color': '#1a1a2e'}},
    xaxis_title=None,
    yaxis_title='Avg Reviews / Month',
    showlegend=False,
    height=400,
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['reviews_per_month'] = fig_to_html(fig6, 'chart_reviews_pm')

# ── Chart 7: Mean Availability ───────────────────────────────────────────

chart_id += 1
fig7 = go.Figure()
avg_avail = [kpi_data[c]['mean_availability'] for c in CITY_ORDER]
med_avail = [kpi_data[c]['median_availability'] for c in CITY_ORDER]
fig7.add_trace(go.Bar(
    x=CITY_ORDER,
    y=avg_avail,
    name='Mean',
    marker_color='#FB8C00',
    text=[f'{v:.0f}' for v in avg_avail],
    textposition='outside',
))
fig7.add_trace(go.Scatter(
    x=CITY_ORDER,
    y=med_avail,
    name='Median',
    mode='markers',
    marker=dict(color='#1a1a2e', size=10, symbol='diamond'),
))
fig7.update_layout(
    title={'text': 'Mean Availability (Days/Year) by City', 'font': {'size': 16, 'color': '#1a1a2e'}},
    xaxis_title=None,
    yaxis_title='Available Days (out of 365)',
    height=400,
    legend=dict(orientation='h', yanchor='bottom', y=1.02, xanchor='right', x=1),
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['availability'] = fig_to_html(fig7, 'chart_availability')

# ── Chart 8: Minimum Nights Distribution ──────────────────────────────────

chart_id += 1
fig8 = go.Figure()
for city in CITY_ORDER:
    city_data = df[df['city'] == city]['minimum_nights'].dropna()
    q95 = city_data.quantile(0.95)
    city_data_clipped = city_data[city_data <= q95]
    fig8.add_trace(go.Violin(
        y=city_data_clipped,
        name=city,
        box_visible=True,
        meanline_visible=True,
        marker_color='#42A5F5',
        line_color='#1a1a2e',
    ))
fig8.update_layout(
    title={'text': 'Minimum Nights Distribution by City (95th Percentile Cap)', 'font': {'size': 16, 'color': '#1a1a2e'}},
    yaxis_title='Minimum Nights',
    showlegend=False,
    height=450,
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False),
)
charts['min_nights'] = fig_to_html(fig8, 'chart_min_nights')

# ── Chart 9: KPI Radar / Scatter for Market Positioning ───────────────────

chart_id += 1
# Price vs Professional Host share colored by Entire Home share
fig9 = go.Figure()
for city in CITY_ORDER:
    fig9.add_trace(go.Scatter(
        x=[kpi_data[city]['median_price']],
        y=[kpi_data[city]['professional_host_pct']],
        mode='markers+text',
        name=city,
        text=[city],
        textposition='top center',
        marker=dict(
            size=kpi_data[city]['entire_home_pct'] * 0.5 + 8,
            color=kpi_data[city]['avg_reviews_per_month'],
            colorscale='Viridis',
            showscale=True,
            colorbar=dict(title='Avg Reviews/Month', thickness=15),
            line=dict(color='#1a1a2e', width=1),
        ),
        hovertemplate=(
            f'<b>{city}</b><br>'
            'Median Price: $%{{x:,.0f}}<br>'
            'Pro Host Share: %{{y:.1f}}%<br>'
            f'Entire Home: {kpi_data[city]["entire_home_pct"]:.1f}%<br>'
            f'Reviews/Mo: {kpi_data[city]["avg_reviews_per_month"]:.2f}<br>'
            '<extra></extra>'
        ),
    ))

fig9.update_layout(
    title={'text': 'Market Positioning: Price vs Professional Host Concentration', 'font': {'size': 16, 'color': '#1a1a2e'}},
    xaxis_title='Median Nightly Price (USD)',
    yaxis_title='Professional Host Share (%)',
    height=500,
    xaxis=dict(gridcolor='#e0e0e0', zeroline=False),
    yaxis=dict(gridcolor='#e0e0e0', zeroline=False, ticksuffix='%'),
)
charts['market_positioning'] = fig_to_html(fig9, 'chart_positioning')

# ── Chart 10: Price Quartile Table ───────────────────────────────────────

chart_id += 1
price_table_data = []
for city in CITY_ORDER:
    prices = df[(df['city'] == city)]['price'].dropna()
    price_table_data.append({
        'City': city,
        '25th Pctl': f'${prices.quantile(0.25):,.0f}',
        'Median': f'${prices.median():,.0f}',
        'Mean': f'${prices.mean():,.0f}',
        '75th Pctl': f'${prices.quantile(0.75):,.0f}',
        '90th Pctl': f'${prices.quantile(0.90):,.0f}',
        'Max': f'${prices.max():,.0f}',
        'Count': len(prices),
    })

# ── Table: KPI Summary ───────────────────────────────────────────────────

kpi_table = []
for city in CITY_ORDER:
    k = kpi_data[city]
    kpi_table.append({
        'City': city,
        'Total Listings': f'{k["total_listings"]:,}',
        'Median Price': f'${k["median_price"]:,.0f}',
        'Mean Price': f'${k["mean_price"]:,.0f}',
        'Entire Home %': f'{k["entire_home_pct"]:.1f}%',
        'Professional Host %': f'{k["professional_host_pct"]:.1f}%',
        'Avg Reviews/Mo': f'{k["avg_reviews_per_month"]:.2f}',
        'Mean Availability': f'{k["mean_availability"]:.0f} days',
        'Avg Min Nights': f'{k["median_min_nights"]:.0f}',
    })

# ══════════════════════════════════════════════════════════════════════════
#  HTML REPORT
# ══════════════════════════════════════════════════════════════════════════

# Price missing note
price_missing_cities = {c: kpi_data[c]['price_missing'] for c in CITY_ORDER}
total_missing = df['price'].isna().sum()
total_rows = len(df)

def build_kpi_card(city, k):
    """Generate a KPI summary card for a city."""
    return f'''
    <div class="city-kpi-card">
        <div class="city-name">{city}</div>
        <div class="city-metrics">
            <div class="metric-row">
                <span class="metric-label">Median Price</span>
                <span class="metric-value">${k["median_price"]:,.0f}</span>
            </div>
